        $roleMap = [
            'Super Admin' => 'Super Admin',
            'IT Admin' => 'IT Admin',
            'IT Staff' => 'IT Staff',
            'Finance Manager' => 'Finance Manager',
            'F&B Manager' => 'F&B Manager',
            'Branch User' => 'Branch User',
            'Coordinator' => 'Coordinator',
        ];

        foreach ($roleMap as $roleName => $spatieRole) {
            $roleObj = Role::firstOrCreate(['name' => $spatieRole, 'guard_name' => 'web']);
            $userIds = DB::table('users')->where('role', $roleName)->pluck('id');
            foreach ($userIds as $uid) {
                DB::table('model_has_roles')->updateOrInsert([
                    'role_id' => $roleObj->id,
                    'model_type' => 'App\\Models\\User',
                    'model_id' => $uid,
